      'المقال الختامي (السادس) للمجموعة الخامسة عبر 10 محاور و6 تمارين قيادية و23 مرجعاً علمياً: قصة إليوت وفرضية العلامة الجسدية لداماسيو (Damasio) ومهمة أيوا (Bechara)، العدوى الانفعالية القيادية وتأثير الغضب والخوف على القرار (Lerner 2015)، القيادة الرنانة مقابل النافرة والأنماط الستة (Goleman & Boyatzis)، الأمن النفسي (Edmondson 1999)، مناظرة كانمان وكلاين حول الحدس القيادي (2009)، الجانب المظلم والتلاعب (Kilduff 2010)، القرار تحت الأزمة، الشورى والرفق والهيبة، والحدود العلمية الحقيقية.',
    summaryEn:
      'Closing Article 6 of Series 5 spanning 10 axes, 6 executive drills, and 23 peer-reviewed references: Damasio’s Somatic Marker Hypothesis and Elliot’s case, Sy et al.’s Contagious Leader and Lerner’s emotion-decision matrix, Resonant vs. Dissonant Leadership (Goleman & Boyatzis), Edmondson’s Psychological Safety, Kahneman & Klein’s 2009 intuition synthesis, Kilduff et al.’s dark side of EQ, crisis decision protocols, Arab leadership anchors (Shura & Rifq), and realistic meta-analytic humility.',
    scientificFramework:
      'فرضية العلامة الجسدية لداماسيو (Damasio 1994; Bechara et al. 2000)، المشاعر واتخاذ القرار (Lerner et al. 2015)، القيادة الرنانة والأنماط الستة (Goleman, Boyatzis & McKee 2002)، الأمن النفسي (Edmondson 1999, 2018)، الخبرة الحدسية (Kahneman & Klein 2009)، القائد المُعدي (Sy et al. 2005)، والجانب المظلم للذكاء العاطفي (Kilduff et al. 2010)',
    scientificFrameworkEn:
      'Somatic Marker Hypothesis (Damasio 1994; Bechara et al. 2000), Emotion & Decision Making (Lerner et al. 2015), Primal/Resonant Leadership (Goleman, Boyatzis & McKee 2002), Psychological Safety (Edmondson 1999, 2018), Intuitive Expertise (Kahneman & Klein 2009), Contagious Leader (Sy et al. 2005), and Dark-Side EQ (Kilduff et al. 2010)',
    clinicalCaseQuoteAr:
      '«القائد العظيم ليس من قتل مشاعره ليصبح موضوعياً، بل من صالحها فأصبح يقرأها كبيانات، ويختبر حدسه كفرضية، ويبني أمناً نفسياً يسمح للحقيقة أن تصله قبل الكارثة.»',
    clinicalCaseQuoteEn:
      '“Great leaders don’t kill emotion in pursuit of objectivity—they read emotion as data, test intuition as a working hypothesis, and build psychological safety so honest warnings arrive before crisis hits.”',
    keyTakeaways: [
      'قصة «إليوت» ومهمة أيوا (Damasio & Bechara) تثبتان أن العقل لا يستطيع الاختيار دون «العلامات الجسدية» والمشاعر كمعلومات (Schwarz).',
      'القائد مُعدٍ عاطفياً عبر الانتباه للمكانة (Sy et al. 2005)، والغضب يشوّه القرار ويرفع الثقة الزائفة بجودته (Lerner et al. 2015).',
      'القيادة الرنانة (Goleman & Boyatzis) تتنقل مرنة بين 4 أنماط على الأقل، بينما تعيش القيادة النافرة في فقاعة معلوماتية خائفة.',
      'الأمن النفسي (Edmondson) هو الشرط الخفي لجودة القرار الجماعي لأن غيابه يخنق المعارضة ويغذي التفكير الجماعي (Groupthink).',
      'الحدس يوثق به فقط في البيئات عالية الصدقية سريعة التغذية الراجعة (Kahneman & Klein 2009)، مع بوصلة أخلاقية تمنع التلاعب (Kilduff 2010) وتواضع علمي يرفض المبالغات.'
    ],
    keyTakeawaysEn: [
      'Elliot’s case and the Iowa Gambling Task prove reason relies on Somatic Markers (Damasio) and Feelings-as-Information (Schwarz) to decide.',
      'Leaders act as group mood regulators (Sy et al. 2005); anger warps choices while inflating false certainty (Lerner et al. 2015).',
      'Resonant leaders flex smoothly across four or more styles, whereas Dissonant leaders trap themselves inside fear-driven information bubbles.',
      'Psychological Safety (Edmondson) governs team decision quality by surfacing dissent and breaking Groupthink.',
      'Trust intuition solely in high-validity, fast-feedback settings (Kahneman & Klein 2009), paired with ethical transparency (Kilduff 2010) and meta-analytic realism.'
    ],
